-- Opt-in developer audit. Read-only player inspection and unlinked scene loads.
-- Jobs are generated by: python tools/runtime_audit.py prepare
-- No actors are spawned, cars switched, pages selected or entitlements changed.
local base=assert(DashboardMod and DashboardMod.root,'Load the dashboard first')
local jobs=DashboardAuditJobsOverride
DashboardAuditJobsOverride=nil
if not jobs then source(base..'inspection/.live-audit-jobs.lua');jobs=DashboardAuditJobs end
if DashboardRuntimeAudit and DashboardRuntimeAudit.stop then DashboardRuntimeAudit:stop() end
local A={enabled=false,jobs=jobs,byId={},seen={},elapsed=0,schemaVersion=1}
DashboardRuntimeAudit=A
local output=base..'inspection/runtime-audit/'
createFolder(output)
for _,folder in ipairs({'scenes','live','actors'}) do createFolder(output..folder) end
for _,job in ipairs(A.jobs) do A.byId[job.id:lower()]=job end

local function finite(v) return type(v)=='number' and v==v and math.abs(v)<math.huge end
local function quote(v)
 return '"'..tostring(v):gsub('\\','\\\\'):gsub('"','\\"'):gsub('[%z\1-\31]',function(c) return string.format('\\u%04x',string.byte(c)) end)..'"'
end
local function json(v)
 local t=type(v)
 if t=='string' then return quote(v) end
 if t=='boolean' then return tostring(v) end
 if t=='number' then return finite(v) and tostring(v) or 'null' end
 if t~='table' then return 'null' end
 local parts={};local array=#v>0
 for k,value in pairs(v) do
  if array and type(k)~='number' then array=false;break end
 end
 if array then
  for i=1,#v do parts[i]=json(v[i]) end
  return '['..table.concat(parts,',')..']'
 end
 for k,value in pairs(v) do parts[#parts+1]=quote(k)..':'..json(value) end
 table.sort(parts);return '{'..table.concat(parts,',')..'}'
end
local function shallow(v,depth)
 local t=type(v)
 if t=='string' or t=='boolean' then return v end
 if t=='number' then return finite(v) and v or nil end
 if t~='table' or depth<1 then return nil end
 local out={};local count=0
 for k,value in pairs(v) do
  count=count+1;if count>100 then break end
  if type(k)=='string' or type(k)=='number' then out[k]=shallow(value,depth-1) end
 end
 return out
end
local function properties(value)
 local out={}
 for k,v in pairs(value) do
  if type(k)=='string' then
   local t=type(v)
   if t=='string' or t=='boolean' or t=='number' then out[k]=shallow(v,0) end
  end
 end
 for _,k in ipairs({'colour','updateColour','highColour','lowColour','minAngle','maxAngle','midAngle','pageSpecificBindings'}) do
  if type(value[k])=='table' then out[k]=shallow(value[k],2) end
 end
 return out
end
local function vector(fn,...)
 if type(fn)~='function' then return nil end
 local ok,a,b,c,d=pcall(fn,...)
 if not ok then return nil end
 return {a,b,c,d}
end
local function nodeInfo(node,materials)
 if type(node)=='table' then node=node.nodeId end
 if type(node)~='number' or node==0 then return nil end
 local ok,name=pcall(getName,node)
 if not ok or type(name)~='string' or name=='' then return nil end
 local result={name=name,translation=vector(getTranslation,node),scale=vector(getScale,node),
               origin=vector(localToWorld,node,0,0,0),axisX=vector(localDirectionToWorld,node,1,0,0),axisY=vector(localDirectionToWorld,node,0,1,0)}
 local shape=ClassIds and getHasClassId and getHasClassId(node,ClassIds.SHAPE)
 if shape then
  result.boundingSphere=vector(getShapeGeometryBoundingSphere,node)
  if materials then
   result.materials={}
   for i=0,getNumOfMaterials(node)-1 do
    local material=getMaterial(node,i);local entry={maps={}}
    if type(getMaterialCustomShaderFilename)=='function' then
     local success,shader=pcall(getMaterialCustomShaderFilename,material)
     if success then entry.shader=shader end
    end
    if type(getMaterialCustomMapFilename)=='function' then
     for _,key in ipairs({'backgroundMap','maskMap1','maskMap2','alphaMap'}) do
      local success,path=pcall(getMaterialCustomMapFilename,material,key)
      if success and type(path)=='string' and path~='' then entry.maps[key]=path end
     end
    end
    result.materials[#result.materials+1]=entry
   end
  end
 end
 return result
end
local function save(kind,job,record)
 record.schemaVersion=1;record.vehicleId=job.id;record.profileSha256=job.profileSha256
 local xml=createXMLFile('dashboardAudit',output..kind..'/'..job.id..'.xml','audit')
 assert(xml and xml~=0,'Cannot create audit output')
 local ok,err=pcall(function() setXMLString(xml,'audit#json',json(record));saveXMLFile(xml) end)
 delete(xml);assert(ok,err)
end
local function definition(job)
 local manager=g_VehicleCatalogueManager
 for _,def in pairs(manager and manager.defs or {}) do
  local path=(def.ActorFile or ''):gsub('\\','/'):lower()
  if def.ID==job.catalogueId and not def.isMod and not def.modName and not path:find('/mods/',1,true) then return def end
 end
end

function A:runScenes(first,last)
 for i=first,math.min(last,#self.jobs) do
  local job=self.jobs[i];local record={scenes={},errors={}}
  local def=definition(job)
  if not def or def.Active~=true then
   record.errors[#record.errors+1]='Official vehicle is not currently active'
  else
   local xml=loadXMLFile('auditActor',def.ActorFile)
   if xml and xml~=0 then
    local ok,err=pcall(saveXMLFileTo,xml,output..'actors/'..job.id..'.xml')
    delete(xml)
    if not ok then record.errors[#record.errors+1]='Actor export failed: '..tostring(err) end
   else record.errors[#record.errors+1]='Mounted actor could not be read' end
   for _,scene in ipairs(job.scenes) do
    assert(scene.file:match('^[dD][aA][tT][aA][sS]?/') or scene.file:match('^[dD][lL][cC][sS]/'))
    local root,reason=loadI3DFile(scene.file,false,false,false)
    local item={source=scene.file,resolvedNames={},nodes={}}
    if root and root~=0 then
     local ok,err=pcall(function()
      local wanted={};for _,name in ipairs(scene.names) do wanted[name]=true end
      local count=0
      local function walk(node)
       count=count+1;assert(count<=20000,'Scene node bound exceeded')
       local name=getName(node)
       if wanted[name] then
        item.resolvedNames[#item.resolvedNames+1]=name
        item.nodes[#item.nodes+1]=nodeInfo(node,true)
       end
       for n=0,getNumOfChildren(node)-1 do walk(getChildAt(node,n)) end
      end
      walk(root)
     end)
     delete(root)
     if not ok then record.errors[#record.errors+1]=scene.file..': '..tostring(err) end
    else record.errors[#record.errors+1]='Scene load failed: '..scene.file..' ('..tostring(reason)..')' end
    record.scenes[#record.scenes+1]=item
   end
  end
  save('scenes',job,record)
  print('DASH_AUDIT_SCENE '..i..'/'..#self.jobs..' '..job.id..' errors='..#record.errors)
 end
 print('DASH_AUDIT_BATCH '..first..'-'..math.min(last,#self.jobs)..' complete')
end

local function read(actor,field,indicator)
 local binding=field
 if indicator then binding={param=field.param,boolean=true} end
 local result={getterAvailable=true}
 if binding.method then result.getterAvailable=type(actor[binding.method])=='function'
 elseif binding.param then
  if type(actor.getVehicleParamValue)~='function' then result.getterAvailable=false
  else
   local ok,found,value=pcall(actor.getVehicleParamValue,actor,binding.param)
   result.getterAvailable=ok and found==true
   result.rawValue=shallow(value,2);result.rawType=type(value)
   if not ok then result.error='Native getter failed: '..tostring(found) end
  end
 end
 local ok,value=pcall(DashboardMod.readNumber,actor,binding)
 if ok then
  result.value=value
  local formatted,text=pcall(DashboardMod.format,binding,value)
  if formatted then result.formatted=text else result.error='Profile formatter failed: '..tostring(text) end
 else result.error='Profile conversion failed: '..tostring(value) end
 return result
end

function A:captureCurrent()
 local data=g_racingManager and g_racingManager.playerVehicleData
 local actor=data and data.vehicleActor
 if not actor then return false,'no player vehicle' end
 local id=DashboardMod.vehicleId(actor)
 if not id then
  local p=DashboardMod.findProfile(actor);id=p and p.id:lower()
 end
 local job=id and self.byId[id:lower()]
 if not job then return false,'no active official digital profile for current actor' end
 local def=definition(job)
 if not def or def.Active~=true then return false,'vehicle is not active and official' end
 -- Exact source identity is checked independently of the selected dashboard.
 for _,c in pairs(actor.components or {}) do
  for _,key in ipairs({'xmlFilename','actorXmlFileName'}) do
   local path=c[key]
   if type(path)=='string' and path:gsub('\\','/'):lower():find('/mods/',1,true) then return false,'mod actor excluded' end
  end
 end
 local motec
 for _,c in pairs(actor.components or {}) do if c.componentType=='MotecComponent' then motec=c;break end end
 if not motec or not motec.masterPage or not motec.pages or not motec.pages[1]
  or not next(motec.masterPage.widgets or {}) then return false,'Motec not ready' end
 local record={complete=true,currentPage=motec.currentPage,activePopup=shallow(motec.activePopup,0),pages={},readings={}}
 for _,page in ipairs({motec.masterPage,motec.pages[1]}) do
  local out={name=page.name,properties=properties(page),widgets={}}
  local count=0
  for name,widget in pairs(page.widgets or {}) do
   count=count+1;assert(count<=400,'Widget bound exceeded')
   local selected=widget.pageSpecificBindings and widget.pageSpecificBindings[motec.pages[1].name]
   out.widgets[#out.widgets+1]={name=name,properties=properties(widget),node=nodeInfo(selected or widget.node,true)}
  end
  table.sort(out.widgets,function(a,b) return a.name<b.name end)
  record.pages[#record.pages+1]=out
 end
 for _,group in ipairs({'fields','gauges','indicators','paletteControls'}) do
  local prefix=group=='fields' and 'field:' or group=='gauges' and 'gauge:' or group=='indicators' and 'indicator:' or 'palette:'
  for _,field in ipairs(job.profile[group] or {}) do record.readings[prefix..field.id]=read(actor,field,group=='indicators') end
 end
 save('live',job,record)
 self.seen[actor]=true
 self.lastVehicle=job.id
 print('DASH_AUDIT_LIVE '..job.id..' captured; import with tools/runtime_audit.py ingest')
 return true,job.id
end

function A:poll(dt)
 if not self.enabled then return end
 self.elapsed=self.elapsed+(finite(dt) and math.max(dt,0) or 0)
 if self.elapsed<1000 then return end
 self.elapsed=0
 local actor=g_racingManager and g_racingManager.playerVehicleData and g_racingManager.playerVehicleData.vehicleActor
 if actor and not self.seen[actor] then
  local ok,captured,reason=pcall(self.captureCurrent,self)
  if not ok then self.enabled=false;print('DASH_AUDIT recorder stopped: '..tostring(captured))
  elseif not captured then self.waiting=reason end
 end
end
function A:stop()
 self.enabled=false
 if update==self.wrapper then update=self.previousUpdate end
end
function A:start()
 assert(type(DashboardMod.readNumber)=='function' and type(DashboardMod.format)=='function','Dashboard renderer not loaded')
 if update~=self.wrapper then
  self.previousUpdate=update
  self.wrapper=function(dt,...)
   if self.previousUpdate then self.previousUpdate(dt,...) end
   self:poll(dt)
  end
  update=self.wrapper
 end
 self.enabled=true
 local ok,captured,reason=pcall(self.captureCurrent,self)
 print('DASH_AUDIT_RECORDER enabled; '..(ok and (captured and 'captured current car' or tostring(reason)) or tostring(captured)))
end
A:start()
